INSERT IGNORE INTO courses (id, slug, title, summary, description, category, level, instructor_id, status, published_at) VALUES (1, 'java-spring-boot-fundamentals', 'Java & Spring Boot Fundamentals', 'Build and ship a production-style REST API with Spring Boot, from project setup to testing.', 'A hands-on onboarding track for new backend engineers. You will build a small REST service, wire it to MySQL, and learn the conventions our teams use in code review.', 'Engineering', 'BEGINNER', 2, 'PUBLISHED', DATE_SUB(NOW(3), INTERVAL 18 DAY));
INSERT IGNORE INTO chapters (id, course_id, title, content, position, duration_min, is_preview) VALUES (1, 1, 'Welcome & environment setup', '## Goals

- Install JDK 17+ and Maven
- Generate a project with Spring Initializr
- Run it locally

```bash
./mvnw spring-boot:run
```

Open `http://localhost:8080/actuator/health` and you should see `UP`.', 1, 8, TRUE);
INSERT IGNORE INTO chapters (id, course_id, title, content, position, duration_min, is_preview) VALUES (2, 1, 'Controllers and request mapping', '## REST controllers

A controller maps HTTP routes to Java methods.

```java
@RestController
@RequestMapping("/api/greetings")
class GreetingController {
    @GetMapping("/{name}")
    Map<String, String> hello(@PathVariable String name) {
        return Map.of("message", "Hello, " + name);
    }
}
```

**Exercise:** add a `POST` endpoint that validates its body with `@Valid`.', 2, 15, FALSE);
INSERT IGNORE INTO chapters (id, course_id, title, content, position, duration_min, is_preview) VALUES (3, 1, 'Persistence with MyBatis', '## Why MyBatis

MyBatis keeps SQL explicit, which makes query plans easy to reason about.

1. Define a mapper interface
2. Write the SQL in XML
3. Enable `map-underscore-to-camel-case`

Use `EXPLAIN` on every new query that touches a large table.', 3, 20, FALSE);
INSERT IGNORE INTO chapters (id, course_id, title, content, position, duration_min, is_preview) VALUES (4, 1, 'Testing your API', '## Test pyramid

- Unit tests for services
- `MockMvc` tests for controllers
- A few end-to-end checks

Keep tests deterministic: no shared mutable state between test methods.', 4, 18, FALSE);

INSERT IGNORE INTO courses (id, slug, title, summary, description, category, level, instructor_id, status, published_at) VALUES (2, 'react-and-nextjs-for-internal-tools', 'React & Next.js for Internal Tools', 'Server-side rendering, routing and data fetching patterns for fast internal dashboards.', 'Learn the App Router, server components and when to reach for client components.', 'Engineering', 'INTERMEDIATE', 4, 'PUBLISHED', DATE_SUB(NOW(3), INTERVAL 15 DAY));
INSERT IGNORE INTO chapters (id, course_id, title, content, position, duration_min, is_preview) VALUES (5, 2, 'Server vs client components', '## Mental model

Server components render on the server and ship **no JavaScript** by default. Mark a file with `''use client''` only when it needs state, effects or browser APIs.', 1, 12, TRUE);
INSERT IGNORE INTO chapters (id, course_id, title, content, position, duration_min, is_preview) VALUES (6, 2, 'Data fetching and caching', '## fetch() on the server

```ts
const res = await fetch(url, { next: { revalidate: 60 } });
```

`revalidate` gives you incremental static regeneration for catalog-style pages.', 2, 16, FALSE);
INSERT IGNORE INTO chapters (id, course_id, title, content, position, duration_min, is_preview) VALUES (7, 2, 'Styling with Tailwind', '## Utility-first CSS

Compose small utilities instead of writing bespoke CSS files. Extract repeated patterns into components, not into `@apply` soup.', 3, 10, FALSE);

INSERT IGNORE INTO courses (id, slug, title, summary, description, category, level, instructor_id, status, published_at) VALUES (3, 'workplace-security-essentials', 'Workplace Security Essentials', 'Phishing, passwords, device hygiene and incident reporting in 30 minutes.', 'Required for all new hires. Covers the security basics every employee is expected to follow.', 'Compliance', 'BEGINNER', 2, 'PUBLISHED', DATE_SUB(NOW(3), INTERVAL 12 DAY));
INSERT IGNORE INTO chapters (id, course_id, title, content, position, duration_min, is_preview) VALUES (8, 3, 'Spotting phishing', '## Red flags

- Urgency and threats
- Mismatched sender domains
- Unexpected attachments

When in doubt, report the message instead of clicking.', 1, 8, TRUE);
INSERT IGNORE INTO chapters (id, course_id, title, content, position, duration_min, is_preview) VALUES (9, 3, 'Passwords and MFA', '## Rules of thumb

1. Use the company password manager
2. Never reuse passwords
3. Turn on MFA everywhere', 2, 7, FALSE);
INSERT IGNORE INTO chapters (id, course_id, title, content, position, duration_min, is_preview) VALUES (10, 3, 'Reporting an incident', '## What to do

Disconnect from the network if you suspect malware, then contact the security team. Speed matters more than certainty.', 3, 6, FALSE);

INSERT IGNORE INTO courses (id, slug, title, summary, description, category, level, instructor_id, status, published_at) VALUES (4, 'sql-for-analysts', 'SQL for Analysts', 'SELECT to window functions: answer business questions straight from the warehouse.', 'Practical SQL with real-world examples drawn from product analytics.', 'Data', 'BEGINNER', 4, 'PUBLISHED', DATE_SUB(NOW(3), INTERVAL 9 DAY));
INSERT IGNORE INTO chapters (id, course_id, title, content, position, duration_min, is_preview) VALUES (11, 4, 'SELECT, WHERE, ORDER BY', '## Your first query

```sql
SELECT id, title FROM courses WHERE status = ''PUBLISHED'' ORDER BY published_at DESC;
```', 1, 10, TRUE);
INSERT IGNORE INTO chapters (id, course_id, title, content, position, duration_min, is_preview) VALUES (12, 4, 'Joins without tears', '## INNER vs LEFT JOIN

A `LEFT JOIN` keeps every row from the left table, filling missing matches with `NULL`.', 2, 14, FALSE);
INSERT IGNORE INTO chapters (id, course_id, title, content, position, duration_min, is_preview) VALUES (13, 4, 'Indexes and query plans', '## B-tree indexes

A composite index on `(user_id, created_at)` lets MySQL find one user''s rows and read them already sorted. Check with `EXPLAIN` and look for `Using filesort`.', 3, 15, FALSE);
INSERT IGNORE INTO chapters (id, course_id, title, content, position, duration_min, is_preview) VALUES (14, 4, 'Window functions', '## Running totals

```sql
SELECT day, SUM(signups) OVER (ORDER BY day) AS cumulative FROM daily_signups;
```', 4, 16, FALSE);

INSERT IGNORE INTO courses (id, slug, title, summary, description, category, level, instructor_id, status, published_at) VALUES (5, 'effective-code-review', 'Effective Code Review', 'Give and receive review feedback that improves code without slowing the team down.', 'Conventions for pull requests, review etiquette and what to look for.', 'Engineering', 'INTERMEDIATE', 2, 'PUBLISHED', DATE_SUB(NOW(3), INTERVAL 6 DAY));
INSERT IGNORE INTO chapters (id, course_id, title, content, position, duration_min, is_preview) VALUES (15, 5, 'Writing a reviewable PR', '## Small and focused

Aim for PRs a reviewer can read in under 20 minutes. Describe *why*, not just *what*.', 1, 9, TRUE);
INSERT IGNORE INTO chapters (id, course_id, title, content, position, duration_min, is_preview) VALUES (16, 5, 'What reviewers look for', '## Checklist

- Correctness and edge cases
- Tests
- Naming and readability
- Security (input validation, authz)', 2, 12, FALSE);

INSERT IGNORE INTO courses (id, slug, title, summary, description, category, level, instructor_id, status, published_at) VALUES (6, 'communicating-as-a-new-engineer', 'Communicating as a New Engineer', 'Stand-ups, design docs and asking good questions during your first 90 days.', 'Soft skills that make onboarding faster for you and your team.', 'Professional Skills', 'BEGINNER', 4, 'PUBLISHED', DATE_SUB(NOW(3), INTERVAL 3 DAY));
INSERT IGNORE INTO chapters (id, course_id, title, content, position, duration_min, is_preview) VALUES (17, 6, 'Asking good questions', '## The template

